-- Generated by scripts/score-cleanup.ts from the registry's score limits (PR #96). Do not edit by hand.
--
-- Removes leaderboard rows that today's score rules (server/plausible.ts) would refuse: finished runs (the weekly
-- board) and personal bests (the all-time board). Each removed row is first copied whole into removed_scores
-- with its reason. A player whose best was removed gets their best remaining finished run as their best.
--
-- To undo (restores every removed row; a rebuilt best is replaced by the original):
--   INSERT OR IGNORE INTO runs (id, user_id, game, started_at, ended_at, score, stats, day, new_best, status)
--     SELECT id, user_id, game, started_at, ended_at, score, stats, day, new_best, status FROM removed_scores WHERE source = 'runs';
--   INSERT OR REPLACE INTO bests (user_id, game, score, stats, at)
--     SELECT user_id, game, score, stats, at FROM removed_scores WHERE source = 'bests';

CREATE TABLE IF NOT EXISTS removed_scores (
  source TEXT NOT NULL,      -- the table the row came from: runs | bests
  reason TEXT NOT NULL,      -- bad_score | too_fast | above_max | implausible_score | bad_stats | run_removed
  removed_at INTEGER NOT NULL,
  id TEXT,                   -- runs
  user_id TEXT NOT NULL,
  game TEXT NOT NULL,
  started_at INTEGER,        -- runs
  ended_at INTEGER,          -- runs
  score,                     -- kept exactly as stored (no type, so a non-integer stays as it was)
  stats TEXT,
  day TEXT,                  -- runs
  new_best INTEGER,          -- runs
  status TEXT,               -- runs
  at INTEGER                 -- bests
);

-- Finished runs.
INSERT INTO removed_scores (source, reason, removed_at, id, user_id, game, started_at, ended_at, score, stats, day, new_best, status)
SELECT 'runs', reason, CAST(strftime('%s', 'now') AS INTEGER) * 1000, id, user_id, game, started_at, ended_at, score, stats, day, new_best, status
FROM (
  SELECT runs.*, CASE
      WHEN typeof(score) <> 'integer' OR score < 0 OR score > 1000000000 THEN 'bad_score'
      WHEN game = 'neon-rush' AND ((ended_at - started_at) / 1000.0) < 2 THEN 'too_fast'
      WHEN game = 'neon-rush' AND score > 500 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'neon-rush' AND json_extract(stats, '$.meters') > 120 * ((ended_at - started_at) / 1000.0) + 50 THEN 'bad_stats'
      WHEN game = 'neon-rush' AND json_extract(stats, '$.nearMisses') > 5 * ((ended_at - started_at) / 1000.0) + 50 THEN 'bad_stats'
      WHEN game = 'memory-grid' AND ((ended_at - started_at) / 1000.0) < 3 THEN 'too_fast'
      WHEN game = 'memory-grid' AND score > 50 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'memory-grid' AND json_extract(stats, '$.accuracy') > 100 THEN 'bad_stats'
      WHEN game = 'memory-grid' AND json_extract(stats, '$.time') < 1 THEN 'bad_stats'
      WHEN game = 'color-recall' AND ((ended_at - started_at) / 1000.0) < 6 THEN 'too_fast'
      WHEN game = 'color-recall' AND score > 5000 THEN 'above_max'
      WHEN game = 'color-recall' AND score > 600 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'color-recall' AND json_extract(stats, '$.accuracy') > 100 THEN 'bad_stats'
      WHEN game = 'color-recall' AND json_extract(stats, '$.bestColor') > 1000 THEN 'bad_stats'
      WHEN game = 'color-recall' AND json_extract(stats, '$.perfects') > 5 THEN 'bad_stats'
      WHEN game = 'letter-pinch' AND ((ended_at - started_at) / 1000.0) < 0 THEN 'too_fast'
      WHEN game = 'letter-pinch' AND score > 800 THEN 'above_max'
      WHEN game = 'letter-pinch' AND score > 800 * ((ended_at - started_at) / 1000.0) + 800 THEN 'implausible_score'
      WHEN game = 'letter-pinch' AND json_extract(stats, '$.spare') > 5 THEN 'bad_stats'
      WHEN game = 'letter-pinch' AND json_extract(stats, '$.guesses') < 1 THEN 'bad_stats'
      WHEN game = 'letter-pinch' AND json_extract(stats, '$.guesses') > 6 THEN 'bad_stats'
      WHEN game = 'letter-pinch' AND json_extract(stats, '$.seconds') < 1 THEN 'bad_stats'
      WHEN game = 'mini-racer' AND ((ended_at - started_at) / 1000.0) < 15 THEN 'too_fast'
      WHEN game = 'mini-racer' AND score > 160 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'launch-control' AND ((ended_at - started_at) / 1000.0) < 5 THEN 'too_fast'
      WHEN game = 'launch-control' AND score > 3600 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'color-lab' AND ((ended_at - started_at) / 1000.0) < 3 THEN 'too_fast'
      WHEN game = 'color-lab' AND score > 6 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'color-lab' AND json_extract(stats, '$.stars') > 2 * ((ended_at - started_at) / 1000.0) + 20 THEN 'bad_stats'
      WHEN game = 'color-lab' AND json_extract(stats, '$.underPar') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'color-lab' AND json_extract(stats, '$.levels') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'color-lab' AND json_extract(stats, '$.parLevels') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'spot-the-glitch' AND ((ended_at - started_at) / 1000.0) < 5 THEN 'too_fast'
      WHEN game = 'spot-the-glitch' AND score > 250 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'spot-the-glitch' AND json_extract(stats, '$.found') > 3 * ((ended_at - started_at) / 1000.0) + 30 THEN 'bad_stats'
      WHEN game = 'spot-the-glitch' AND json_extract(stats, '$.clean') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'spot-the-glitch' AND json_extract(stats, '$.pictures') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'wheres-the-ball' AND ((ended_at - started_at) / 1000.0) < 4 THEN 'too_fast'
      WHEN game = 'wheres-the-ball' AND score > 600 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'wheres-the-ball' AND json_extract(stats, '$.found') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'wheres-the-ball' AND json_extract(stats, '$.fastest') < 1 THEN 'bad_stats'
      WHEN game = 'wheres-the-ball' AND json_extract(stats, '$.levels') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'wing-it' AND ((ended_at - started_at) / 1000.0) < 2 THEN 'too_fast'
      WHEN game = 'wing-it' AND score > 4 * ((ended_at - started_at) / 1000.0) + 40 THEN 'implausible_score'
      WHEN game = 'wing-it' AND json_extract(stats, '$.pillars') > 1.5 * ((ended_at - started_at) / 1000.0) + 15 THEN 'bad_stats'
      WHEN game = 'wing-it' AND score <> 1 * json_extract(stats, '$.pillars') + 3 * json_extract(stats, '$.feathers') THEN 'bad_stats'
      WHEN game = 'crosswire' AND ((ended_at - started_at) / 1000.0) < 8 THEN 'too_fast'
      WHEN game = 'crosswire' AND score > 1250 THEN 'above_max'
      WHEN game = 'crosswire' AND score > 100 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'crosswire' AND json_extract(stats, '$.clean') > 1 THEN 'bad_stats'
      WHEN game = 'crosswire' AND json_extract(stats, '$.seconds') < 1 THEN 'bad_stats'
      WHEN game = 'wait-what' AND ((ended_at - started_at) / 1000.0) < 10 THEN 'too_fast'
      WHEN game = 'wait-what' AND score > 160 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'wait-what' AND score > 150 * json_extract(stats, '$.correct') THEN 'implausible_score'
      WHEN game = 'crass-act' AND ((ended_at - started_at) / 1000.0) < 60 THEN 'too_fast'
      WHEN game = 'crass-act' AND score > 0.1 * ((ended_at - started_at) / 1000.0) + 1 THEN 'implausible_score'
      WHEN game = 'to-scale' AND ((ended_at - started_at) / 1000.0) < 3 THEN 'too_fast'
      WHEN game = 'to-scale' AND score > 1000 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'to-scale' AND json_extract(stats, '$.bullseyes') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'square-deal' AND ((ended_at - started_at) / 1000.0) < 3 THEN 'too_fast'
      WHEN game = 'square-deal' AND score > 600 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'outta-here' AND ((ended_at - started_at) / 1000.0) < 3 THEN 'too_fast'
      WHEN game = 'outta-here' AND score > 1000 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'outta-here' AND json_extract(stats, '$.levels') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'outta-here' AND json_extract(stats, '$.perfect') > 1 * ((ended_at - started_at) / 1000.0) + 10 THEN 'bad_stats'
      WHEN game = 'gloop' AND ((ended_at - started_at) / 1000.0) < 3 THEN 'too_fast'
      WHEN game = 'gloop' AND score > 60 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'gloop' AND json_extract(stats, '$.biggest') > 11 THEN 'bad_stats'
      WHEN game = 'gut-check' AND ((ended_at - started_at) / 1000.0) < 0 THEN 'too_fast'
      WHEN game = 'gut-check' AND score > 300 THEN 'above_max'
      WHEN game = 'gut-check' AND score > 2 * ((ended_at - started_at) / 1000.0) + 20 THEN 'implausible_score'
      WHEN game = 'star-grid' AND ((ended_at - started_at) / 1000.0) < 1 THEN 'too_fast'
      WHEN game = 'star-grid' AND score > 3600 THEN 'above_max'
      WHEN game = 'star-grid' AND score > 250 * ((ended_at - started_at) / 1000.0) + 1200 THEN 'implausible_score'
      WHEN game = 'star-grid' AND json_extract(stats, '$.time') < 10 THEN 'bad_stats'
      WHEN game = 'fussbox' AND ((ended_at - started_at) / 1000.0) < 5 THEN 'too_fast'
      WHEN game = 'fussbox' AND score > 1000 THEN 'above_max'
      WHEN game = 'fussbox' AND score > 250 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'fussbox' AND json_extract(stats, '$.correct') > 8 THEN 'bad_stats'
      WHEN game = 'whatsit' AND ((ended_at - started_at) / 1000.0) < 0 THEN 'too_fast'
      WHEN game = 'whatsit' AND score > 1000 THEN 'above_max'
      WHEN game = 'whatsit' AND score > 1000 * ((ended_at - started_at) / 1000.0) + 1000 THEN 'implausible_score'
      WHEN game = 'belot' AND ((ended_at - started_at) / 1000.0) < 20 THEN 'too_fast'
      WHEN game = 'belot' AND score > 3000 THEN 'above_max'
      WHEN game = 'belot' AND score > 20 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'backgammon' AND ((ended_at - started_at) / 1000.0) < 30 THEN 'too_fast'
      WHEN game = 'backgammon' AND score > 1000 THEN 'above_max'
      WHEN game = 'backgammon' AND score > 20 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'backgammon' AND json_extract(stats, '$.points') > 9 THEN 'bad_stats'
      WHEN game = 'sigilfall' AND ((ended_at - started_at) / 1000.0) < 20 THEN 'too_fast'
      WHEN game = 'sigilfall' AND score > 1500 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
      WHEN game = 'crater-crew' AND ((ended_at - started_at) / 1000.0) < 1 THEN 'too_fast'
      WHEN game = 'crater-crew' AND score > 300 * ((ended_at - started_at) / 1000.0) + 50 THEN 'implausible_score'
    END AS reason
  FROM runs WHERE status = 'ok'
) WHERE reason IS NOT NULL;

DELETE FROM runs WHERE status = 'ok' AND id IN (SELECT id FROM removed_scores WHERE source = 'runs');

-- Personal bests: by their own score and stats, or because the run they came from was removed.
INSERT INTO removed_scores (source, reason, removed_at, user_id, game, score, stats, at)
SELECT 'bests', reason, CAST(strftime('%s', 'now') AS INTEGER) * 1000, user_id, game, score, stats, at
FROM (
  SELECT b.*, COALESCE(CASE
        WHEN typeof(score) <> 'integer' OR score < 0 OR score > 1000000000 THEN 'bad_score'
        WHEN game = 'memory-grid' AND json_extract(stats, '$.accuracy') > 100 THEN 'bad_stats'
        WHEN game = 'memory-grid' AND json_extract(stats, '$.time') < 1 THEN 'bad_stats'
        WHEN game = 'color-recall' AND score > 5000 THEN 'above_max'
        WHEN game = 'color-recall' AND json_extract(stats, '$.accuracy') > 100 THEN 'bad_stats'
        WHEN game = 'color-recall' AND json_extract(stats, '$.bestColor') > 1000 THEN 'bad_stats'
        WHEN game = 'color-recall' AND json_extract(stats, '$.perfects') > 5 THEN 'bad_stats'
        WHEN game = 'letter-pinch' AND score > 800 THEN 'above_max'
        WHEN game = 'letter-pinch' AND json_extract(stats, '$.spare') > 5 THEN 'bad_stats'
        WHEN game = 'letter-pinch' AND json_extract(stats, '$.guesses') < 1 THEN 'bad_stats'
        WHEN game = 'letter-pinch' AND json_extract(stats, '$.guesses') > 6 THEN 'bad_stats'
        WHEN game = 'letter-pinch' AND json_extract(stats, '$.seconds') < 1 THEN 'bad_stats'
        WHEN game = 'wheres-the-ball' AND json_extract(stats, '$.fastest') < 1 THEN 'bad_stats'
        WHEN game = 'wing-it' AND score <> 1 * json_extract(stats, '$.pillars') + 3 * json_extract(stats, '$.feathers') THEN 'bad_stats'
        WHEN game = 'crosswire' AND score > 1250 THEN 'above_max'
        WHEN game = 'crosswire' AND json_extract(stats, '$.clean') > 1 THEN 'bad_stats'
        WHEN game = 'crosswire' AND json_extract(stats, '$.seconds') < 1 THEN 'bad_stats'
        WHEN game = 'wait-what' AND score > 150 * json_extract(stats, '$.correct') THEN 'implausible_score'
        WHEN game = 'gloop' AND json_extract(stats, '$.biggest') > 11 THEN 'bad_stats'
        WHEN game = 'gut-check' AND score > 300 THEN 'above_max'
        WHEN game = 'star-grid' AND score > 3600 THEN 'above_max'
        WHEN game = 'star-grid' AND json_extract(stats, '$.time') < 10 THEN 'bad_stats'
        WHEN game = 'fussbox' AND score > 1000 THEN 'above_max'
        WHEN game = 'fussbox' AND json_extract(stats, '$.correct') > 8 THEN 'bad_stats'
        WHEN game = 'whatsit' AND score > 1000 THEN 'above_max'
        WHEN game = 'belot' AND score > 3000 THEN 'above_max'
        WHEN game = 'backgammon' AND score > 1000 THEN 'above_max'
        WHEN game = 'backgammon' AND json_extract(stats, '$.points') > 9 THEN 'bad_stats'
      END,
    (SELECT 'run_removed' FROM removed_scores r
      WHERE r.source = 'runs' AND r.user_id = b.user_id AND r.game = b.game AND r.score = b.score AND r.ended_at = b.at)) AS reason
  FROM bests b
) WHERE reason IS NOT NULL;

DELETE FROM bests WHERE EXISTS (
  SELECT 1 FROM removed_scores r
  WHERE r.source = 'bests' AND r.user_id = bests.user_id AND r.game = bests.game AND r.score IS bests.score AND r.at = bests.at
);

-- The best remaining finished run (highest score, earliest first) takes a removed best's place.
INSERT OR IGNORE INTO bests (user_id, game, score, stats, at)
SELECT user_id, game, score, stats, ended_at FROM (
  SELECT user_id, game, score, COALESCE(stats, '{}') AS stats, ended_at,
    ROW_NUMBER() OVER (PARTITION BY user_id, game ORDER BY score DESC, ended_at ASC) AS n
  FROM runs
  WHERE status = 'ok' AND score > 0
    AND EXISTS (SELECT 1 FROM removed_scores r WHERE r.source = 'bests' AND r.user_id = runs.user_id AND r.game = runs.game)
) WHERE n = 1;
